#!/usr/bin/env python3
"""Comparison tooling: P4 interface comparison; checks example outputs (Python stdlib)."""
import argparse
import json
from pathlib import Path
import re
import shutil
import subprocess
import tempfile

OPTIONS = ("A", "B", "C")
CONTEXTS = ("retail", "progression:main", "anniversary:main", "era:main", "sod:main",
            "sod:replay", "progression:replay")
HERE = Path(__file__).resolve().parent
# Literal expected labels are independent of the emitter's banner constructor.
EXPECTED_HEADERS = {
    "retail": b"-- Generated by Parser --phase-example (ordinary Retail default; outside P1-P4). Edit the selected source inputs, then regenerate.\n",
    "progression:main": b"-- Generated by Parser --phase-example (P4 interface example). Edit the selected source inputs, then regenerate.\n",
    "anniversary:main": b"-- Generated by Parser --phase-example (P4 interface example). Edit the selected source inputs, then regenerate.\n",
    "era:main": b"-- Generated by Parser --phase-example (P4 interface example). Edit the selected source inputs, then regenerate.\n",
    "sod:main": b"-- Generated by Parser --phase-example (P4 interface example). Edit the selected source inputs, then regenerate.\n",
    "sod:replay": b"-- Generated by Parser --phase-example (P4 synthetic comparison fixture). Edit the selected source inputs, then regenerate.\n",
    "progression:replay": b"-- Generated by Parser --phase-example (P4 synthetic comparison fixture). Edit the selected source inputs, then regenerate.\n",
}


## @brief Run a command and assert whether it succeeded as expected.
# @param command Executable and argument tokens; stdout and stderr are captured as text.
# @param succeeds Whether a zero exit code is required.
# @return CompletedProcess with captured stdout, stderr and the asserted exit status.
def run(command, *, succeeds=True):
    result = subprocess.run([str(value) for value in command], capture_output=True, text=True)
    if (result.returncode == 0) != succeeds:
        raise AssertionError(f"Unexpected exit {result.returncode}: {command}\n{result.stdout}\n{result.stderr}")
    return result


## @brief Locate the policy input containing a context and key for the selected interface.
# @param context Flavor:profile context used by this compile or policy lookup.
# @param key Unqualified policy key whose owning input is requested.
# @param option Proposed interface A, B or C.
# @param root Copied example input directory containing the selected interface files.
# @return Owning JSON path, complete document and mutable context policy map.
def policy_file(root, option, context, key):
    if option != "C":
        path = root / "profiles" / (context.replace(":", "/") + ".json")
        data = json.loads(path.read_text(encoding="utf-8"))
        return path, data, data["content"]
    for path in sorted((root / "policies").glob("*.json")):
        data = json.loads(path.read_text(encoding="utf-8"))
        if key in data.get(context, {}):
            return path, data, data[context]
    raise AssertionError(f"No policy {context}:{key}")


## @brief Exercise the three example interfaces, malformed inputs and route invariants.
def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--parser", type=Path, required=True, help="actual Parser.exe, or the shared-source local harness DLL")
    parser.add_argument("--launcher", action="append", default=[], help="prefix token; repeat for e.g. --launcher dotnet --launcher exec")
    parser.add_argument("--lua", default="lua5.1", help="Lua 5.1 executable")
    parser.add_argument("--input-dir", type=Path, default=HERE / "input")
    parser.add_argument("--output", "--output-dir", dest="output_dir", type=Path, help="keep the 21 compiled native Lua modules here")
    args = parser.parse_args()
    command = args.launcher + [str(args.parser.resolve())]
    run([args.lua, "-e", "assert(_VERSION == 'Lua 5.1', 'Lua 5.1 is required')"])
    with tempfile.TemporaryDirectory(prefix="att-phase-examples-") as temporary:
        scratch = Path(temporary)
        output = args.output_dir.resolve() if args.output_dir else scratch / "output"
        output.mkdir(parents=True, exist_ok=True)
        source = args.input_dir.resolve()
        for lua_source in sorted(source.rglob("*.lua")):
            # Parse with the actual WoW-language version without executing it.
            quoted = json.dumps(str(lua_source), ensure_ascii=False)
            run([args.lua, "-e", f"assert(loadfile({quoted}))"])
        for context in CONTEXTS:
            for option in OPTIONS:
                target = output / option / f"{context.replace(':', '-')}.lua"
                target.parent.mkdir(parents=True, exist_ok=True)
                run(command + ["--phase-example", option, source, context, target])
                native = target.read_bytes()
                expected_header = EXPECTED_HEADERS[context]
                if not native.startswith(expected_header) or b"\r" in native:
                    raise AssertionError(f"{option} {context}: missing generated header or non-LF output")
            slug = context.replace(":", "-") + ".lua"
            baseline = (output / "A" / slug).read_bytes()
            for option in ("B", "C"):
                if (output / option / slug).read_bytes() != baseline:
                    raise AssertionError(f"{context}: native {option} output differs from A")
        behavior = run([args.lua, HERE / "verify.lua", HERE / "evaluate.lua", output])
        print(behavior.stdout.strip())
        print("21 native Lua outputs: full A/B/C equivalence and six-case Lua 5.1 behavior passed")

        # Anonymous scopes must flatten while preserving every cumulative key.
        # The direct child deliberately has its own key: treating the outer
        # scope as a default would silently bypass the disabled ancestor.
        scope_input = scratch / "anonymous-scope"
        (scope_input / "profiles/sod").mkdir(parents=True)
        (scope_input / "sources.lua").write_text('''return {
    inst(742, { groups = {
        { progressionKey = "original", groups = {
            { progressionKey = "original", g = {
                e(1536, { progressionKey = "later", groups = { i(19003) } }),
            } },
            { progressionKey = "original", timeline = { "added 1.0" }, groups = { i(19004) } },
        } },
        e(1537, { progressionKey = "rework", groups = { i(19005) } }),
    } }),
}''', encoding="utf-8")
        (scope_input / "profiles/sod/main.json").write_text(json.dumps({
            "milestones": ["vanilla.1"], "content": {
                "original": {"status": "disabled", "windows": []},
                "later": {"windows": [{"from": "vanilla.1"}]},
                "rework": {"windows": [{"from": "vanilla.1"}]},
            }}), encoding="utf-8")
        scope_check = scratch / "scope-check.lua"
        scope_check.write_text('''local phased, retail = dofile(arg[1]), dofile(arg[2])
local evaluate = dofile(arg[3])
local nodes = phased.groups[1].groups
assert(#nodes == 3 and nodes[1].encounterID == 1536, "scope must flatten")
assert(#nodes[1].progressionScopes == 2 and nodes[1].progressionScopes[1] == "sod:main:original" and nodes[1].progressionScopes[2] == "sod:main:later", "ancestor and child scopes must both survive, without duplicates")
assert(nodes[2].timeline[1] == "added 1.0" and nodes[2].groups[1].itemID == 19004, "conditioned node must remain")
assert(#nodes[3].progressionScopes == 1 and nodes[3].progressionScopes[1] == "sod:main:rework", "rework must not inherit original")
assert(phased.policies[nodes[1].progressionScopes[1]].status == "disabled")
local route = evaluate.find(phased, {itemID = 19003}, "vanilla.1",
    ---Accept ordinary conditions while checking inherited scopes.
    ---@return boolean
    function() return true end)
assert(not route.obtainable and #route.routes == 1 and route.routes[1].schedule == "disabled", "an open child cannot bypass the disabled ancestor")
assert(#route.routes[1].scopeStates == 2 and route.routes[1].scopeStates[2].state == "active", "the child rule must also be evaluated")
assert(evaluate.find(phased, {itemID = 19005}, "vanilla.1",
    ---Accept ordinary conditions for the independent route.
    ---@return boolean
    function() return true end).obtainable, "the independent rework must remain open")
local conditioned = evaluate.find(phased, {itemID = 19004}, "vanilla.1",
    ---Reject nodes with an ordinary timeline condition.
    ---@param node table
    ---@return boolean
    function(node) return node.timeline == nil end)
assert(not conditioned.routes[1].conditionsPass, "the visible parent's ordinary condition must remain")
local r = retail.groups[1].groups
assert(#r == 3 and r[1].encounterID == 1536 and r[2].timeline, "Retail must retain the flat ordinary shape")
---Assert that Retail output contains no progression scopes at any depth.
---@param nodes table[]
local function noScopes(nodes)
    for _, node in ipairs(nodes) do
        assert(not node.progressionScopes, "Retail must not retain scopes")
        noScopes(node.groups or {})
    end
end
noScopes(retail.groups)
''', encoding="utf-8")
        scope_outputs = []
        for context in ("sod:main", "retail"):
            target = scratch / (context.replace(":", "-") + "-scope.lua")
            run(command + ["--phase-example", "A", scope_input, context, target])
            scope_outputs.append(target)
        run([args.lua, scope_check, *scope_outputs, HERE / "evaluate.lua"])
        print("Anonymous scope inheritance, flat shape and Retail passed")

        # Exercise removal/reopening through the actual compiler, not only the
        # evaluator unit fixture. These are deliberately synthetic milestones.
        windows_input = scratch / "window-roundtrip"
        shutil.copytree(source, windows_input)
        profile = windows_input / "profiles/sod/main.json"
        document = json.loads(profile.read_text(encoding="utf-8"))
        insertion = document["milestones"].index("vanilla.5") + 1
        document["milestones"][insertion:insertion] = ["fixture.5.1", "fixture.5.2", "fixture.5.10"]
        changed_policy = {"windows": [{"from": "fixture.5.1", "until": "fixture.5.2"}, {"from": "fixture.5.10"}]}
        document["content"]["raid.bwl.sod20"] = changed_policy
        document["content"]["brd.dungeon"] = {"windows": [{"from": "start"}]}
        profile.write_text(json.dumps(document), encoding="utf-8")
        (windows_input / "catalogs/sod/main.json").write_text(json.dumps({"milestones": document["milestones"]}), encoding="utf-8")
        policy_path, policy_document, content = policy_file(windows_input, "C", "sod:main", "raid.bwl.sod20")
        content["raid.bwl.sod20"] = changed_policy
        policy_path.write_text(json.dumps(policy_document), encoding="utf-8")
        start_path, start_document, start_content = policy_file(windows_input, "C", "sod:main", "brd.dungeon")
        start_content["brd.dungeon"] = {"windows": [{"from": "start"}]}
        start_path.write_text(json.dumps(start_document), encoding="utf-8")
        windows_outputs = []
        for option in OPTIONS:
            target = scratch / f"windows-{option}.lua"
            run(command + ["--phase-example", option, windows_input, "sod:main", target])
            windows_outputs.append(target)
        if len({path.read_bytes() for path in windows_outputs}) != 1:
            raise AssertionError("A/B/C removal/reopening compilation differs")
        run([args.lua, HERE / "verify.lua", HERE / "evaluate.lua", "--windows", windows_outputs[0]])
        print("Native subphase/removal/reopening roundtrip passed for A/B/C")

        # Compare inputs that differ only in reserved comments at every object
        # level, including selection, catalog, policy, and window objects.
        ## @brief Add documentation comments recursively for input-consumption checks.
        # @param documented Whether to add reserved comments at every object level.
        # @param value JSON fixture value to copy recursively with reserved comments.
        # @return A recursively copied JSON value with comments added only when requested.
        def with_comments(value, documented):
            if isinstance(value, dict):
                result = {key: with_comments(child, documented) for key, child in value.items()
                          if key != "$comment"}
                if documented:
                    result["$comment"] = "Fixture documentation"
                return result
            if isinstance(value, list):
                return [with_comments(child, documented) for child in value]
            return value

        clean_input = scratch / "clean-json"
        documented_input = scratch / "documented-json"
        for directory, documented in ((clean_input, False), (documented_input, True)):
            shutil.copytree(source, directory)
            for path in directory.rglob("*.json"):
                data = json.loads(path.read_text(encoding="utf-8"))
                path.write_text(json.dumps(with_comments(data, documented), ensure_ascii=False), encoding="utf-8")
        for context in CONTEXTS:
            for option in OPTIONS:
                clean_output = scratch / "clean.lua"
                documented_output = scratch / "documented.lua"
                run(command + ["--phase-example", option, clean_input, context, clean_output])
                run(command + ["--phase-example", option, documented_input, context, documented_output])
                if clean_output.read_bytes() != documented_output.read_bytes():
                    raise AssertionError(f"{option} {context}: comments changed compiled output")
        print("Documented JSON matches comment-free output for all options and contexts")

        count = 0
        ## @brief Compile a mutated fixture and require rejection, optionally checking its diagnostic.
        # @param context Flavor:profile context used by this compile or policy lookup.
        # @param diagnostic Optional expected case-insensitive stderr fragment.
        # @param mutate Callback that changes only this case’s copied input directory.
        # @param name Unique temporary case name used in failure diagnostics.
        # @param option Proposed interface A, B or C.
        def rejected(name, option, mutate, context="sod:main", diagnostic=None):
            nonlocal count
            case = scratch / name
            shutil.copytree(source, case)
            mutate(case)
            target = case / "sentinel.lua"
            sentinel = b"previous output must survive\n"
            target.write_bytes(sentinel)
            result = run(command + ["--phase-example", option, case, context, target], succeeds=False)
            if target.read_bytes() != sentinel:
                raise AssertionError(f"{name}: failed compile changed its previous output")
            if diagnostic and diagnostic.lower() not in result.stderr.lower():
                raise AssertionError(f"{name}: wrong diagnostic: {result.stderr}")
            if list(case.glob("sentinel.lua.*.tmp")):
                raise AssertionError(f"{name}: temporary output leaked")
            count += 1

        ## @brief Produce a fixture mutation for a selected policy.
        # @param change Callback receiving the mutable policy map and selected key.
        # @param key Unqualified policy key whose owning input is requested.
        # @param option Proposed interface A, B or C.
        # @return Mutation callback applying the chosen change to one copied policy input.
        def edit_policy(option, key, change):
            ## @brief Apply the supplied policy change to this copied fixture.
            # @param case Isolated copied input directory to mutate.
            def mutate(case):
                path, document, policies = policy_file(case, option, "sod:main", key)
                change(policies, key)
                path.write_text(json.dumps(document, ensure_ascii=False), encoding="utf-8")
            return mutate

        for option in ("A", "C"):
            cases = {
                "missing": ("raid.bwl.sod20", lambda p, k: p.pop(k)),
                "missing-child-under-disabled": ("raid.bwl.draconic-for-dummies", lambda p, k: p.pop(k)),
                "disabled-with-window": ("raid.bwl.original", lambda p, k: p.__setitem__(k, {"status": "disabled", "windows": [{"from": "vanilla.5"}]})),
                "unknown-with-window": ("dfc.dungeon", lambda p, k: p.__setitem__(k, {"status": "unknown", "windows": [{"from": "vanilla.4"}]})),
                "reversed": ("raid.bwl.sod20", lambda p, k: p.__setitem__(k, {"windows": [{"from": "vanilla.5", "until": "vanilla.4"}]})),
                "unknown-subphase": ("raid.bwl.sod20", lambda p, k: p.__setitem__(k, {"windows": [{"from": "vanilla.4.10"}]})),
                "empty-scheduled": ("raid.bwl.sod20", lambda p, k: p.__setitem__(k, {"windows": []})),
                "explicit-scheduled": ("raid.bwl.sod20", lambda p, k: p.__setitem__(k, {"status": "scheduled", "windows": [{"from": "vanilla.5"}]})),
                "unknown-policy-field": ("raid.bwl.sod20", lambda p, k: p[k].__setitem__("window", [])),
                "unknown-window-field": ("raid.bwl.sod20", lambda p, k: p[k]["windows"][0].__setitem__("unti1", "vanilla.7")),
                "orphan": ("raid.bwl.sod20", lambda p, k: p.__setitem__("typo.unused", {"windows": [{"from": "vanilla.5"}]})),
                "array-policy": ("raid.bwl.sod20", lambda p, k: p.__setitem__(k, [])),
                "overlapping-windows": ("raid.bwl.sod20", lambda p, k: p.__setitem__(k, {"windows": [{"from": "vanilla.4", "until": "vanilla.7"}, {"from": "vanilla.5"}]})),
                "object-windows": ("raid.bwl.sod20", lambda p, k: p.__setitem__(k, {"windows": {}})),
            }
            for name, (key, change) in cases.items():
                rejected(f"{option}-{name}", option, edit_policy(option, key, change))
            ## @brief Introduce a duplicate field into the selected JSON input.
            # @param case Isolated copied input directory to mutate.
            # @param option Proposed interface A, B or C.
            def duplicate(case, option=option):
                path, _, _ = policy_file(case, option, "sod:main", "raid.bwl.sod20")
                text = path.read_text(encoding="utf-8")
                quoted = json.dumps("raid.bwl.sod20")
                text, changed = re.subn(re.escape(quoted) + r"\s*:", quoted + ':{"windows":[]},' + quoted + ':', text, count=1)
                assert changed == 1
                path.write_text(text, encoding="utf-8")
            rejected(f"{option}-duplicate-json", option, duplicate, diagnostic="duplicate")

        ## @brief Replace text in a copied profile fixture.
        # @param text Replacement profile JSON text, including deliberately invalid fixtures.
        # @return Mutation callback writing the supplied text into the copied SoD main profile.
        def replace_profile(text):
            return lambda case: (case / "profiles/sod/main.json").write_text(text, encoding="utf-8")
        for index, value in enumerate((None, True, 1, [], {})):
            rejected(f"invalid-comment-{index}", "A", replace_profile(
                json.dumps({"$comment": value, "milestones": [], "content": {}})), diagnostic="$comment")
        for index, first in enumerate(('"first"', 'null')):
            rejected(f"duplicate-comment-{index}", "A", replace_profile(
                '{"$comment":' + first + ',"$comment":"second","milestones":[],"content":{}}'),
                diagnostic="duplicate")
        rejected("nested-invalid-comment", "A", edit_policy(
            "A", "raid.bwl.sod20", lambda policies, key: policies[key].__setitem__("$comment", None)),
            diagnostic="$comment")
        rejected("json-slash-comment", "A", replace_profile(
            '{ // not JSON\n "milestones":[],"content":{}}'))
        rejected("malformed-json", "A", replace_profile("{"))
        rejected("array-json-root", "A", replace_profile("[]"), diagnostic="object")
        for index, invalid in enumerate(("01", "+1", "1.", ".1", "1e", "NaN", "Infinity")):
            rejected(f"json-number-{index}", "A", replace_profile('{"milestones":[' + invalid + '],"content":{}}'))

        ## @brief Remove the selected fragment from a copied input.
        # @param case Isolated copied input directory to mutate.
        def selected_fragment_missing(case):
            path = case / "selection.json"
            document = json.loads(path.read_text(encoding="utf-8"))
            selected = document["sod:main"]
            slot = next(key for key, value in selected.items() if key != "$comment" and value is not None)
            selected[slot] = "fragments/not-present.lua"
            path.write_text(json.dumps(document), encoding="utf-8")
        rejected("B-missing-selected-fragment", "B", selected_fragment_missing)
        ## @brief Add a selection without a corresponding group slot.
        # @param case Isolated copied input directory to mutate.
        def unused_selection(case):
            path = case / "selection.json"
            document = json.loads(path.read_text(encoding="utf-8"))
            document["sod:main"]["typo-unused"] = None
            path.write_text(json.dumps(document), encoding="utf-8")
        rejected("B-unused-selection", "B", unused_selection, diagnostic="unused")
        ## @brief Remove a required group selection.
        # @param case Isolated copied input directory to mutate.
        def missing_selection(case):
            path = case / "selection.json"
            document = json.loads(path.read_text(encoding="utf-8"))
            document["sod:main"].pop(next(key for key in document["sod:main"] if key != "$comment"))
            path.write_text(json.dumps(document), encoding="utf-8")
        rejected("B-missing-selection", "B", missing_selection, diagnostic="missing group")
        rejected("unknown-context", "A", lambda case: None, context="unknown:main")
        rejected("reserved-start-milestone", "A", replace_profile('{"milestones":["start"],"content":{}}'), diagnostic="boundary")
        rejected("duplicate-milestone", "A", replace_profile('{"milestones":["vanilla.1","vanilla.1"],"content":{}}'), diagnostic="duplicate")
        ## @brief Introduce a duplicate Lua field in a source fixture.
        # @param case Isolated copied input directory to mutate.
        def duplicate_lua(case):
            (case / "sources.lua").write_text('return { inst(1, { itemID=2, itemID=3 }) }', encoding="utf-8")
        rejected("duplicate-lua-field", "A", duplicate_lua, context="retail", diagnostic="duplicate")
        ## @brief Insert an unsupported Lua side effect into a source fixture.
        # @param case Isolated copied input directory to mutate.
        def attempted_effect(case):
            # Even an excluded expression is never executed: arbitrary calls are
            # outside the literal grammar and fail before output publication.
            (case / "sources.lua").write_text('return { inst(1, { flavors={"sod"}, groups={i(2, {poison=evil()})} }) }', encoding="utf-8")
        rejected("excluded-arbitrary-helper", "A", attempted_effect, context="retail", diagnostic="unsupported")
        print(f"{count} rejected-input cases: previous output preserved; no temporary outputs leaked")


if __name__ == "__main__":
    main()
